        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    def find_arrangement(current_arrangement, used_numbers):
        if len(current_arrangement) == 7:
            # Check if the last and first numbers add up to a prime
            if is_prime(current_arrangement[0] + current_arrangement[-1]):
                return current_arrangement
            else:
                return None

        last_number = current_arrangement[-1]
        for next_number in range(1, 8):
            if next_number not in used_numbers:
                if is_prime(last_number + next_number):
                    result = find_arrangement(current_arrangement + [next_number], used_numbers | {next_number})
                    if result:
                        return result
        return None

    for start_number in range(1, 8):
        result = find_arrangement([start_number], {start_number})
        if result:
            return result
    return None

